public class SolicitudCredito {
    private final String idCliente;
    private final String tipoCliente;
    private final double scoreFinanciero;
    private final String estado;
    private static final double TASA_BASE = 40;

    public SolicitudCredito(String idCliente, String tipoCliente, double scoreFinanciero, String estado) {
        if (idCliente == null || idCliente.isBlank() || tipoCliente == null || tipoCliente.isBlank())
            throw new IllegalArgumentException("Id y tipo requeridos");
        this.idCliente = idCliente;
        this.tipoCliente = tipoCliente;
        this.scoreFinanciero = scoreFinanciero;
        this.estado = estado;
    }

    public static SolicitudCredito desdeCampos(String[] tokens) {
        if (tokens.length != 5)
            throw new IllegalArgumentException("Se esperan 5 columnas");
        double ingresos = Double.parseDouble(tokens[2]);
        double deudas = Double.parseDouble(tokens[3]);
        if (ingresos < 1000 || ingresos > 15000)
            throw new IllegalArgumentException("Ingresos no aptos");
        if (deudas < 0 || deudas >= ingresos)
            throw new IllegalArgumentException("Deudas no aptas");
        double score = (1 - (deudas / ingresos)) * 100;
        return new SolicitudCredito(tokens[0], tokens[1], score, tokens[4]);
    }

    public String getIdCliente() { return idCliente; }
    public String getTipoCliente() { return tipoCliente; }
    public double getScoreFinanciero() { return scoreFinanciero; }
    public String getEstado() { return estado; }
    public double getTasaInteresAnual() { return TASA_BASE + (100 - scoreFinanciero) * 0.8; }
}

