    private final String estado;
    private final int diasCobertura;

    public Consumo(String id, String rubro, long importeCentavos, long bonificacionCentavos, String estado) {
        this(id, rubro, importeCentavos, bonificacionCentavos, estado, 0);
    }

    public Consumo(String id, String rubro, long importeCentavos, long bonificacionCentavos, String estado,
                   int diasCobertura) {
        if (id.isBlank() || rubro.isBlank())
            throw new IllegalArgumentException("id y rubro requeridos");
        if (importeCentavos <= 0)
            throw new IllegalArgumentException("importe inválido");
        if (bonificacionCentavos < 0 || bonificacionCentavos > importeCentavos)
            throw new IllegalArgumentException("bonificación inválida");
        if (!List.of(0, 30, 90, 180).contains(diasCobertura))
            throw new IllegalArgumentException("plazo de cobertura inválido: " + diasCobertura);
        if (diasCobertura > 0 && importeCentavos - bonificacionCentavos > TOPE_ASEGURADO)
            throw new IllegalArgumentException("neto supera el tope asegurado");
        this.id = id;
        this.rubro = rubro;
        this.importeCentavos = importeCentavos;
        this.bonificacionCentavos = bonificacionCentavos;
        this.estado = estado;
        this.diasCobertura = diasCobertura;
    }

    public static Consumo desdeCampos(String[] c) {
        if (c.length != 5 && c.length != 6)
            throw new IllegalArgumentException("se esperan 5 o 6 campos");
        int dias = c.length == 6 ? Integer.parseInt(c[5]) : 0;
        return new Consumo(c[0], c[1], Long.parseLong(c[2]), Long.parseLong(c[3]), c[4], dias);
    }

